fn enc_host_allowance(out: &mut ::std::vec::Vec<u8>, v: &HostAllowance, depth: i32) {
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "hosts");
    out.extend_from_slice(b": ");
    strs(out, &v.hosts, depth + 1);
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

fn enc_pick_request(out: &mut ::std::vec::Vec<u8>, v: &PickRequest, depth: i32) {
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "model");
    out.extend_from_slice(b": ");
    esc(out, &v.model);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "fresh");
    out.extend_from_slice(b": ");
    out.extend_from_slice(if v.fresh { b"true" } else { b"false" });
    if let Some(value) = &v.allowed {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "allowed");
        out.extend_from_slice(b": ");
        enc_host_allowance(out, value, depth + 1);
    }
    if !v.profile.is_empty() {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "profile");
        out.extend_from_slice(b": ");
        esc(out, &v.profile);
    }
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

