fn enc_reasoning_support(out: &mut ::std::vec::Vec<u8>, v: &ReasoningSupport, depth: i32) {
    let n = v.efforts.len();
    if n > 8 { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "efforts");
    out.extend_from_slice(b": ");
    strs(out, &v.efforts, depth + 1);
    if v.budget {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "budget");
        out.extend_from_slice(b": ");
        out.extend_from_slice(if v.budget { b"true" } else { b"false" });
    }
    if let Some(value) = &v.default_effort {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "default_effort");
        out.extend_from_slice(b": ");
        esc(out, value);
    }
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

fn enc_model_capabilities(out: &mut ::std::vec::Vec<u8>, v: &ModelCapabilities, depth: i32) {
    let n = v.input.len();
    if n > 16 { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    for oa_element in v.input.iter() {
    let n = oa_element.len();
    if !(1..=256).contains(&n) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    let n = v.output.len();
    if n > 16 { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    for oa_element in v.output.iter() {
    let n = oa_element.len();
    if !(1..=256).contains(&n) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    let n = v.extensions.len();
    if n > 64 { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    out.push(b'{');
    let mut first = true;
    if !v.input.is_empty() {
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "input");
        out.extend_from_slice(b": ");
        strs(out, &v.input, depth + 1);
    }
    if !v.output.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "output");
        out.extend_from_slice(b": ");
        strs(out, &v.output, depth + 1);
    }
    if let Some(value) = &v.tools {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "tools");
        out.extend_from_slice(b": ");
        out.extend_from_slice(if *value { b"true" } else { b"false" });
    }
    if let Some(value) = &v.structured_output {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "structured_output");
        out.extend_from_slice(b": ");
        out.extend_from_slice(if *value { b"true" } else { b"false" });
    }
    if let Some(value) = &v.reasoning {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "reasoning");
        out.extend_from_slice(b": ");
        enc_reasoning_support(out, value, depth + 1);
    }
    if !v.extensions.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "extensions");
        out.extend_from_slice(b": ");
        strs(out, &v.extensions, depth + 1);
    }
    if !first {
        out.push(b'\n');
        pad(out, depth);
    }
    out.push(b'}');
}

