fn service_check_host_allowance(_v: &HostAllowance) -> ::std::result::Result<(), Refusal> {
    Ok(())
}

fn service_check_pick_request(v: &PickRequest) -> ::std::result::Result<(), Refusal> {
    if let Some(value) = &v.allowed {
        service_check_host_allowance(value)?;
    }
    Ok(())
}

fn service_check_offer_request(_v: &OfferRequest) -> ::std::result::Result<(), Refusal> {
    Ok(())
}

fn service_check_oa_router_modalities_arguments(v: &OARouterModalitiesArguments) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    let n = v.cursor.len();
    if n > 256 { return r.refuse("bad_value"); }
    Ok(())
}

fn service_check_oa_router_models_arguments(_v: &OARouterModelsArguments) -> ::std::result::Result<(), Refusal> {
    Ok(())
}

fn service_check_oa_router_hosts_arguments(_v: &OARouterHostsArguments) -> ::std::result::Result<(), Refusal> {
    Ok(())
}

fn service_check_oa_router_pick_arguments(v: &OARouterPickArguments) -> ::std::result::Result<(), Refusal> {
    service_check_pick_request(&v.request)?;
    Ok(())
}

fn service_check_oa_router_offer_arguments(v: &OARouterOfferArguments) -> ::std::result::Result<(), Refusal> {
    service_check_offer_request(&v.request)?;
    Ok(())
}

fn service_check_oa_router_observe_offer_arguments(v: &OARouterObserveOfferArguments) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    let n = v.cursor.len();
    if n > 256 { return r.refuse("bad_value"); }
    service_check_offer_request(&v.request)?;
    Ok(())
}

